"""Record actual emitted section/local-frame costs without inventing latency."""
from pathlib import Path
import hashlib,json,re
ROOT=Path(__file__).resolve().parents[1];RECEIPT='reviews/v5/expansion/legacy_advanced_uart/current_validation.json'
def sha(p):return hashlib.sha256(p.read_bytes()).hexdigest()
def main():
 d=json.loads((ROOT/RECEIPT).read_text());assert d['passed'];rows={r['label']:r for r in d['checks']};profiles=[]
 for cc in ['arm-none-eabi-gcc','clang']:
  for opt in ['-O0','-O3']:
   tag=cc+opt;r=rows[tag+' cost'];raw=(ROOT/r['raw']).read_text();sections=[]
   for name,size,address in re.findall(r'^(\S+)\s+(\d+)\s+(\d+)\s*$',raw,re.M):sections.append(dict(name=name,bytes=int(size),address=int(address)))
   stack=[]
   for path,h in d['outputs_sha256'].items():
    if '/'+tag+'/' in path and path.endswith('.su'):
     assert sha(ROOT/path)==h
     for line in (ROOT/path).read_text().splitlines():
      parts=line.split('\t')
      if len(parts)==3:stack.append(dict(function=parts[0].split(':')[-1],local_frame_bytes=int(parts[1]),kind=parts[2],source=path))
   assert stack and sections
   imports={unit:(ROOT/rows[tag+' '+unit+' imports']['raw']).read_text().strip().splitlines() for unit in ['core','target','serial','firmware','helpers']}
   profiles.append(dict(profile=tag,sections=sections,local_stack_frames=stack,object_imports=imports,linked_imports=(ROOT/rows[tag+' image closure']['raw']).read_text(),helpers='Original assessor/execution/support.c; compiler-generated byte operations remain visible in imports/map. No compiler runtime archive.'))
 out=dict(passed=True,input_sha256={RECEIPT:sha(ROOT/RECEIPT),'tools/summarize_uart_costs.py':sha(Path(__file__))},profiles=profiles,comparison=dict(polling='Up to polls status reads; source-byte read and DR write per step; O(n) CPU byte work.',interrupt='Same per-byte work plus interrupt entry/exit and schedule cost; final TC interrupt distinct; no executed interrupt latency in this campaign.',dma='Constant setup/stop/status CPU work plus O(n) bus reads/writes; caller memory retained until EN0; line retained until TC. No zero-cost or latency-bound claim.'),limits=['Emitted section sizes and compiler local frames are observed; local frames are not complete call-chain/interrupt peak stack.','No physical latency, DMA throughput or energy measured.','Different optimization/targets require rebuilding; these are not portable golden costs.'])
 p=ROOT/'reviews/v5/expansion/legacy_advanced_uart/cost_analysis.json';p.write_text(json.dumps(out,indent=2)+'\n');print(dict(passed=True,profiles=len(profiles),local_frames=sum(len(p['local_stack_frames']) for p in profiles)))
if __name__=='__main__':main()
